import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Criterio inverso del fondamentale","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/ff/fff.md","filePath":"lezioni/f_geometria-del-piano-euclideo/ff/fff.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/ff/fff.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="criterio-inverso-del-fondamentale" tabindex="-1">Criterio inverso del fondamentale <a class="header-anchor" href="#criterio-inverso-del-fondamentale" aria-label="Permalink to “Criterio inverso del fondamentale”">​</a></h1><p>Ricordiamoci che è valido il quinto postulato: <strong>Data una retta e un punto fuori di essa, da quel punto si può tracciare solo una retta parallela alla retta data</strong>.</p><p>Possiamo ora dimostrare che:</p><h2 id="se-due-rette-sono-parallele-allora-tagliate-da-una-trasversale-formano-angoli-alterni-interni-uguali" tabindex="-1">Se due rette sono parallele, allora tagliate da una trasversale formano angoli alterni interni uguali <a class="header-anchor" href="#se-due-rette-sono-parallele-allora-tagliate-da-una-trasversale-formano-angoli-alterni-interni-uguali" aria-label="Permalink to “Se due rette sono parallele, allora tagliate da una trasversale formano angoli alterni interni uguali”">​</a></h2><p>Anche qui facciamo la dimostrazione per assurdo.</p><p class="text-blue"><strong>Ipotesi:</strong> [<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi><mo>∥</mo><mi>b</mi></mrow><annotation encoding="application/x-tex">a \\parallel b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span>]{.text-blue} <strong>Tesi:</strong> [<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>angolo\xA0</mtext><mn>1</mn><mo>=</mo><mtext>angolo\xA0</mtext><mn>2</mn></mrow><annotation encoding="application/x-tex">\\text{angolo } 1 = \\text{angolo } 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">angolo\xA0</span></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">angolo\xA0</span></span><span class="mord">2</span></span></span></span>]</p><p>Dimostrazione: Supponiamo che gli angoli non siano uguali e che, ad esempio, l&#39;angolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> sia più piccolo dell&#39;angolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>, allora io posso prendere, a partire dalla trasversale, un angolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mn>3</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{3}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">3</span></span></span></span> che sia uguale all&#39;angolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>. Ma per il criterio precedente allora la retta <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi></mrow><annotation encoding="application/x-tex">c</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> sarà parallela alla retta <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi></mrow><annotation encoding="application/x-tex">a</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span>; per il quinto postulato, dovendoci essere una sola parallela, la retta <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi></mrow><annotation encoding="application/x-tex">b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span> non può essere parallela alla retta <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi></mrow><annotation encoding="application/x-tex">a</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span> contro l&#39;ipotesi. Quindi il criterio è vero.</p><blockquote><p><strong>Nota:</strong> Lo so benissimo che dalla figura si vede chi è parallelo e chi no, ma tu devi immaginare le rette quasi sovrapposte e che si discostino di un centimetro dopo chilometri; io ho dovuto disegnarle così per esigenze grafiche (dove lo trovo un foglio lungo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn><mtext>\xA0km</mtext></mrow><annotation encoding="application/x-tex">3\\text{ km}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord">3</span><span class="mord text"><span class="mord">\xA0km</span></span></span></span></span>?).</p></blockquote><p>Avendo dimostrato sia il criterio che il criterio inverso, i due fatti:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Rette\xA0parallele</mtext><mtext>  </mtext><mo>⟺</mo><mtext>  </mtext><mtext>Angoli\xA0alterni\xA0interni\xA0uguali</mtext></mrow><annotation encoding="application/x-tex">\\text{Rette parallele} \\iff \\text{Angoli alterni interni uguali} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Rette\xA0parallele</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⟺</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Angoli\xA0alterni\xA0interni\xA0uguali</span></span></span></span></span></span></p><p>saranno d&#39;ora in poi equivalenti, cioè se trovi in un problema che due rette sono parallele nelle ipotesi scriverai che gli angoli sono uguali e dimostrerai che gli angoli alterni interni sono uguali per dimostrare che le rette sono parallele.</p>`,11)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};